/// —— 补按前先抬一次,既收掉设备端可能存在的"幽灵槽位"(同一个 pid 在设备端
/// 若真的按着,再 DOWN 一次会把老手指顶掉、留下位置错乱),也避免同 pid 反复
/// 只按不抬(见 control.rs 的警告)。
fn confirm_wheel_down(ctl: &ControlClient, m: &Mapper, j: usize, w: &Wheel, st: &mut WheelState) {
    let pid = wheel_pid(j);
    let (lx, ly) = st.last;
    // 圆心按落指时的同一口径重算:标准轮盘由几何中心算,自定义/执行轮盘
    // 直接取配置圆心(并钳屏 —— 落指时就是这么钳的)。
    let (cx, cy) = if w.kind == WheelKind::Standard {
        wheel_center_px(m, w)
    } else {
        clamp_to_screen(m, m.point(w.cx, w.cy).0, m.point(w.cx, w.cy).1)
    };
    ctl.touch_up(pid, lx, ly);
    ctl.touch_down(pid, cx, cy);
    ctl.touch_move(pid, lx, ly);
    st.cur? no.
    st.sent_at = Some(Instant::now());
