    // 为准,不以表里有没有残值为准。
    if tail > 0
        && fresh_press
        && let Some(g) = gate
        && now < g
    {
        scheduled.push((
            g,
            SchedAct::Redispatch {
                idx,
                lane,
                code: bind.key,
            },
        ));
        return None;
    }"}

