/// 这样一次组合只会切换一次,按住不放也不会连发。
fn ctrl_alt_chord(code: u16, pressed: bool, ctrl_down: bool, alt_down: bool) -> bool {
    pressed && ctrl_down && alt_down && (is_ctrl(code) || is_alt(code))
}

/// 内置 Ctrl+Alt 手势是否该给用户让位;`Some(name)` = 让位,并说明是被哪个键位占了
/// (DF-12)。
///
/// 用户把 `toggle_key` / `suspend_key` 显式绑成 Ctrl 或 Alt 时,内置的"Ctrl+Alt
/// 交还/收回鼠标"会和它抢同一批按键 —— 一次误按就让 `aim.released` 翻转、视角失效
/// **且不自愈**。此时内置手势整体让位(用户的显式绑定优先于内置约定)。
///
/// **判据只看配置,不看"本次按下的是哪个键"**:用户绑的是 Ctrl 时,冲突发生在
/// 随后按下的 **Alt** 那一下 —— 若写成"本次按下的键属于某个 KeySet",Alt 那一下
/// 就漏判了。只要这两个键位里含 Ctrl/Alt,内置手势就闭嘴。
///
/// 左右 Ctrl/Alt 都算([`is_ctrl`]/[`is_alt`] 覆盖 29/97/56/100);
/// 默认配置里两个键位都是空集合 ⇒ 返回 `None` ⇒ 行为与修复前逐字一致。
pub(crate) fn chord_yield_reason(aim: &Aim) -> Option<&'static str> {
    for (ks, name) in [
        (&aim.toggle_key, "FPS 模式开关键"),
        (&aim.suspend_key, "按住才退出"),
    ] {
        if ks.as_slice().iter().any(|k| is_ctrl(*k) || is_alt(*k)) {
            return Some(name);
        }
    }
    None
