    #[test]
    fn tail_delay_latches_auto_repeat_and_schedules_only_once() {
        const KEY: u16 = 41;
        let hold = Action::Hold {
            x: 0.5,
            y: 0.5,
            radius: 0.03,
        };
        let mut f = TailFixture::new(KEY, 30, hold, true);
        // 正常按下 + 抬起:挂上冷却
        f.fire(true, true);
