        let cool_until = f.gates.bind_gate(0).expect("抬起后应当挂上冷却");

        // 冷却里按住不放:自动重复(每一发都不是上升沿)既不许落点,
        // 也不许每个事件各排一条补捉。
        for _ in 0..8 {
            f.fire(true, false);
